  return proc as unknown as EncoderProcess;
}

edits.new_str:
function drainPipe(stream: ReadableStream<Uint8Array> | number | null): void {
  if (!stream || typeof stream === "number") return;
  const reader = stream.getReader();
  async function drain() {
    try { while (true) { const { done } = await reader.read(); if (done) break; } }
    catch { /* pipe closed */ }
    finally { try { reader.releaseLock(); } catch { /* already released */ } }
  }
  void drain();
}

function defaultSpawn(command: string[]): EncoderProcess {
  const proc = Bun.spawn(command, { stdin: "pipe", stdout: "pipe", stderr: "pipe" });
  if (!proc.stdin || typeof proc.stdin === "number") throw new Error("JPEG encoder stdin unavailable");
  if (!proc.stdout || typeof proc.stdout === "number") throw new Error("JPEG encoder stdout unavailable");
  drainPipe(proc.stderr);
  return proc as unknown as EncoderProcess;
}

private killProc(proc: EncoderProcess): void {
  try {
    (proc as unknown as { pid: number }).pid ?? 0;
    try { process.kill(-(proc as unknown as { pid: number }).pid, "SIGKILL"); return; } catch { /* not detached or group gone */ }
  } catch { /* pid not available */ }
  try { proc.kill("SIGKILL"); } catch { /* already exited */ }
}

stop(): Promise<void> {
  if (this.stopping) return this.stopping;
  this.closed = true;
  const proc = this.proc;
  this.proc = undefined;
  const failure = this.failure ?? new Error("JPEG encoder stopped");
  this.failure = failure;
  this.rejectPending(failure);
  if (!proc) return Promise.resolve();

  try {
    const ended = proc.stdin.end?.();
    if (ended instanceof Promise) void ended.catch(() => undefined);
  } catch { /* stdin already closed */ }
  this.killProc(proc);

  this.stopping = Promise.race([
    proc.exited.then(() => undefined, () => undefined),
    Bun.sleep(1000),
  ]).then(() => { this.stopping = undefined; });
  return this.stopping;
}

