let enabled = false;
let moving = false;
const ws = new WebSocket("ws://10.67.0.1:8080/ws");
ws.onopen = () => { console.log("OPEN"); ws.send(JSON.stringify({type:"enable",on:true})); };
ws.onmessage = (event) => {
  const m = JSON.parse(event.data);
  if (m.type === "motorState") {
    enabled = m.enabled;
    moving = m.moving;
    console.log("motorState:", JSON.stringify(m));
    if (enabled && !m.moving) {
      console.log(">> SEND motor yaw +1 on:true");
      ws.send(JSON.stringify({type:"motor",axis:"yaw",dir:1,on:true,slow:false}));
      setTimeout(() => {
        console.log(">> SEND motor yaw +1 on:false");
        ws.send(JSON.stringify({type:"motor",axis:"yaw",dir:1,on:false}));
        setTimeout(() => { console.log(">> SEND enable off"); ws.send(JSON.stringify({type:"enable",on:false})); setTimeout(() => ws.close(), 200); }, 1000);
      }, 1500);
    }
  } else if (m.type === "error") { console.log("ERROR:", m.error); }
};
ws.onclose = () => { console.log("WS CLOSED, moving=" + moving); process.exit(0); };
ws.onerror = () => { console.log("WS ERROR"); process.exit(1); };
setTimeout(() => process.exit(1), 15000);
